var i=42;var a=[{id:`cooking-042-01`,theoryId:42,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is citrus zest?`,ua:`Що таке цедра цитрусових?`},explanation:{en:`The colored outer peel contains much of the fragrant citrus oil.`,ua:`Зовнішній забарвлений шар містить значну частину ароматичних цитрусових олій.`},options:[{id:`a`,text:{en:`The colored aromatic outer layer, avoiding bitter white pith`,ua:`Забарвлений ароматний зовнішній шар без гіркої білої частини`}},{id:`b`,text:{en:`Only the white pith`,ua:`Лише біла частина`}},{id:`c`,text:{en:`The citrus seeds`,ua:`Насіння цитрусових`}}],answer:{optionIds:[`a`]}},{id:`cooking-042-02`,theoryId:42,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Grating increases exposed surface area and may accelerate moisture loss.`,ua:`Натирання збільшує відкриту площу поверхні та може прискорювати втрату вологи.`},explanation:{en:`Smaller fragments have more exposed area for evaporation and oxidation.`,ua:`Дрібніші частинки мають більшу відкриту площу для випаровування й окиснення.`},answer:{value:!0}},{id:`cooking-042-03`,theoryId:42,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match preparation methods with their common results.`,ua:`Поєднайте методи підготовки з типовим результатом.`},explanation:{en:`Each method creates a different particle size and texture.`,ua:`Кожен метод створює інший розмір частинок і текстуру.`},leftItems:[{id:`l1`,text:{en:`Grating`,ua:`Натирання`}},{id:`l2`,text:{en:`Zesting`,ua:`Зняття цедри`}},{id:`l3`,text:{en:`Mashing`,ua:`Розминання`}}],rightItems:[{id:`r3`,text:{en:`Soft crushed potato texture`,ua:`М’яка розім’ята картопля`}},{id:`r2`,text:{en:`Aromatic citrus peel shavings`,ua:`Ароматні частинки цитрусової шкірки`}},{id:`r1`,text:{en:`Small shreds of cheese`,ua:`Дрібна стружка сиру`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-042-04`,theoryId:42,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order safe zesting before squeezing a lemon.`,ua:`Розташуйте кроки безпечного зняття цедри перед вичавлюванням лимона.`},explanation:{en:`Zesting intact fruit first provides control and limits pith removal.`,ua:`Знімати цедру з цілого плоду простіше й легше не зачепити білу частину.`},steps:[{id:`s2`,text:{en:`Gently remove thin colored peel using a suitable grater`,ua:`Обережно зняти тонкий забарвлений шар відповідною терткою`}},{id:`s1`,text:{en:`Wash and dry the lemon`,ua:`Вимити й обсушити лимон`}},{id:`s3`,text:{en:`Cut and squeeze juice into a separate bowl`,ua:`Розрізати й вичавити сік в окрему миску`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-042-05`,theoryId:42,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You need garlic aroma distributed through a sauce without visible chunks. Best approach?`,ua:`Потрібен аромат часнику в соусі без помітних шматочків. Що зробити?`},explanation:{en:`Crushing/grating ruptures cells and helps distribute garlic flavor.`,ua:`Роздавлювання або натирання руйнує клітини й сприяє розподілу смаку часнику.`},options:[{id:`a`,text:{en:`Use very large raw slices`,ua:`Додати дуже великі сирі скибки`}},{id:`b`,text:{en:`Crush or finely grate the garlic`,ua:`Роздавити або дрібно натерти часник`}},{id:`c`,text:{en:`Keep unpeeled cloves on the plate`,ua:`Залишити неочищені зубчики на тарілці`}}],answer:{optionIds:[`b`]}}];var r={theoryId:42,exercises:a};export{r as default,a as exercises,i as theoryId};